38			TaxRateBP *int           `json:"tax_rate_bp"`
39			Plan      *store.OrgPlan `json:"plan"`
40		}
41		if !decode(w, r, &in) {
42			return
43		}
44		o, err := s.store.UpdateOrg(p.OrgID, func(o *store.Org) error {
45			if in.Name != nil {
46				o.Name = *in.Name
47			}
48			if in.TimeZone != nil {
49				o.TimeZone = *in.TimeZone
50			}
