// APIKey lets a member call the API. It acts as that member, with the member's current role.
// The store keeps only the SHA-256 hash of the token (Hash) and its last four characters (Last4). Token is set only on
// the key returned when it is created, the one answer that shows the full token; it is never stored.
type APIKey struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
	Name       string     `json:"name"`
	Hash       string     `json:"hash"`
	Last4      string     `json:"last4"`
	Token      string     `json:"token,omitempty"`
	CreatedAt  time.Time  `json:"created_at"`

