	}
	if len(seen) != 1000 {
		t.Fatalf("%d distinct tokens out of 1000", len(seen))
	}
}

func TestTouchAPIKeyAtMostOncePerMinute(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleMember, t0)
	k, _ := s.CreateAPIKey(o.ID, u.ID, "k", t0)
	lastUsed := func() time.Time {
		t.Helper()
		got, _ := s.APIKey(o.ID, k.ID)
		if got.LastUsedAt == nil {
			t.Fatal("no last use recorded")
		}
		return *got.LastUsedAt
	}
	s.TouchAPIKey(k.ID, t0)
	s.TouchAPIKey(k.ID, t0.Add(59*time.Second))
	if !lastUsed().Equal(t0) {
		t.Fatalf("a use 59 seconds later was recorded: %v", lastUsed())
	}
	s.TouchAPIKey(k.ID, t0.Add(time.Minute))
	if !lastUsed().Equal(t0.Add(time.Minute)) {
		t.Fatalf("a use a minute later was not recorded: %v", lastUsed())
	}
	s.TouchAPIKey(k.ID, t0.Add(90*time.Second))
	if !lastUsed().Equal(t0.Add(time.Minute)) {
		t.Fatalf("a use 30 seconds later was recorded: %v", lastUsed())
	}
}

