		Users:   []User{{ID: "usr_000002", Email: "ann@example.com", Name: "Ann"}},
		Members: []Member{{OrgID: "org_000001", UserID: "usr_000002", Role: RoleOwner}},
		APIKeys: []APIKey{{ID: "key_000003", OrgID: "org_000001", UserID: "usr_000002", Name: "old", Token: token}},
	}
	s, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	got, ok := s.APIKeyByToken(token)
	if !ok || got.ID != "key_000003" || got.Token != "" || got.Hash != hashToken(token) || got.Last4 != "0003" {
