func TestAPIKeyTokensAreHashed(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleMember, t0)
	k, err := s.CreateAPIKey(o.ID, u.ID, "CI", t0)
	if err != nil {
		t.Fatal(err)
	}
	if !regexp.MustCompile(`^tly_[A-Za-z0-9]{40}$`).MatchString(k.Token) {
		t.Fatalf("token %q", k.Token)
	}
	sum := sha256.Sum256([]byte(k.Token))
	if k.Hash != hex.EncodeToString(sum[:]) || k.Last4 != k.Token[len(k.Token)-4:] {
		t.Fatalf("key = %+v", k)
	}
	stored, ok := s.APIKey(o.ID, k.ID)
	if !ok || stored.Token != "" || stored.Hash != k.Hash || stored.Last4 != k.Last4 {
		t.Fatalf("stored key = %+v %v", stored, ok)
	}
	if got, ok := s.APIKeyByToken(k.Token); !ok || got.ID != k.ID {
		t.Fatalf("APIKeyByToken = %+v %v", got, ok)
	}
	if _, ok := s.APIKeyByToken(k.Hash); ok {
		t.Fatal("the stored hash works as a token")
	}
	for _, key := range s.APIKeys(o.ID) {
		if key.Token != "" {
			t.Fatalf("listed key holds its token: %+v", key)
		}
	}
	b, _ := json.Marshal(s.Export())
	if strings.Contains(string(b), k.Token) {
		t.Fatal("the store holds the token")
	}
}

