func TestAPIKeyTokenShownOnlyOnCreate(t *testing.T) {
	e := apitest.New(t)
	var created map[string]any
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &created)
	token, _ := created["token"].(string)
	if !regexp.MustCompile(`^tly_[A-Za-z0-9]{40}$`).MatchString(token) || created["last4"] != token[len(token)-4:] {
		t.Fatalf("created key = %v", created)
	}
	if _, ok := created["hash"]; ok {
		t.Fatalf("created key shows its hash: %v", created)
	}
	r := e.Do("GET", "/v1/api-keys", e.Acme.Key, nil)
	if r.Code != http.StatusOK || strings.Contains(string(r.Body), token) || strings.Contains(string(r.Body), `"hash"`) {
		t.Fatalf("list: %s", r)
	}
	var keys struct {
		Items []map[string]any `json:"items"`
	}
	if err := json.Unmarshal(r.Body, &keys); err != nil {
		t.Fatal(err)
	}
	for _, k := range keys.Items {
		if _, ok := k["token"]; ok || k["last4"] == "" {
			t.Fatalf("listed key = %v", k)
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", token, nil, nil)
}

