218	func (s *Server) createAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
219		var in struct {
220			Name string `json:"name"`
221		}
222		if !decode(w, r, &in) {
223			return
224		}
225		k, err := s.store.CreateAPIKey(p.OrgID, p.UserID, in.Name, s.clock.Now())
226		if err != nil {
227			s.storeError(w, err)
228			return
229		}
230		writeJSON(w, http.StatusCreated, keyView(k))
231	}
232	
233	func (s *Server) revokeAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
234		if _, err := s.store.RevokeAPIKey(p.OrgID, r.PathValue("id"), s.clock.Now()); err != nil {
235			s.storeError(w, err)
236			return
237		}
238		w.WriteHeader(http.StatusNoContent)
239	}
